import sys; sys.path.insert(0,'/home/claude/honglifecalc/build')
from enrich_lib import build, table, faq_html
form='''<form class="card" id="form" onsubmit="return false"><h2>Your numbers</h2><style>.money::before{content:"£"}</style><label class="f"><span>Income before the pension contribution (salary, profits etc.)</span><div class="money"><input id="i" inputmode="decimal" value="60,000"></div><small>Used to find the rate of relief, including the 60% band between £100,000 and £125,140.</small></label><label class="f"><span>Your net contribution (what you pay in)</span><div class="money"><input id="c" inputmode="decimal" value="4,000"></div><small>For a relief-at-source scheme (personal pensions, SIPPs, many workplace schemes).</small></label></form>'''
calc='''function calc(){const c=num('c'),g=c/.8,base=g-c,i=num('i');const extra=Math.min(g,Math.max(0,i-50270))*.2+Math.min(g,Math.max(0,i-125140))*.05;
 let pa=0;if(i>100000){const lb=Math.min(12570,(i-100000)/2),la=Math.min(12570,Math.max(0,i-g-100000)/2);pa=(lb-la)*.4}
 const cost=c-extra-pa;
 return big('Gross pension contribution',gbp(g,0),'Real cost to you '+gbp(cost,0))+kv([['You pay',gbp(c,0)],['Basic-rate relief added by provider (20% of gross)',gbp(base,0),'pos'],['Extra relief via Self Assessment / tax code',gbp(extra,0),'pos']].concat(pa?[['Personal allowance won back (60% band)',gbp(pa,0),'pos']]:[]).concat([['Effective cost',gbp(cost,0),'t'],['Effective relief rate',pc((g-cost)/g,0)]]))+'<p class="note">Annual allowance £60,000 (or 100% of UK earnings if lower), tapered to £10,000 when adjusted income exceeds £260,000. England, Wales and Northern Ireland tax bands; Scottish rates differ.</p>'}'''
FAQ=[
("How much does a £4,000 pension contribution cost a higher-rate taxpayer?","£4,000 paid in becomes £5,000 in the pension once the provider adds £1,000 of basic-rate relief. A higher-rate taxpayer with at least £5,000 of income taxed at 40% claims another £1,000 through Self Assessment, so the real cost is £3,000."),
("How do I claim higher-rate pension tax relief?","Through your Self Assessment tax return, or by writing to or calling HMRC if you don't complete a return — HMRC usually adjusts your tax code. Relief at source only adds the basic 20% automatically. You can claim for the current year and the previous four tax years."),
("What is the 60% tax trap?","Between £100,000 and £125,140 of adjusted net income you lose £1 of personal allowance for every £2 of income, so the effective rate is 60%. A gross pension contribution that brings your income down restores the allowance — £5,000 of net contributions (£6,250 gross... ) can be worth relief of up to 60%. In the calculator, £8,000 paid in on £110,000 of income costs £4,000 for £10,000 in the pension."),
("Is there a limit on pension tax relief?","Yes. You get relief on contributions up to 100% of your UK relevant earnings (or £3,600 gross if you earn less than that), within the £60,000 annual allowance. The allowance tapers down to £10,000 for adjusted income above £260,000, and is £10,000 (the money purchase annual allowance) if you have flexibly accessed a pension."),
("Is salary sacrifice better than relief at source?","Usually, because salary sacrifice also saves employee National Insurance (8% or 2%) and often employer NI. From April 2029 NI savings will only apply to the first £2,000 a year of sacrificed salary; income tax relief is unchanged.")]
FAQ[2]=("What is the 60% tax trap?","Between £100,000 and £125,140 of adjusted net income you lose £1 of personal allowance for every £2 of income, so the effective tax rate is 60%. Pension contributions reduce adjusted net income and win the allowance back. In the calculator, paying in £8,000 net on £110,000 of income puts £10,000 in the pension for a real cost of £4,000 — 60% relief.")
art='''<h2>How pension tax relief works (2026/27)</h2>
<p>The government tops up pension contributions with tax relief at your highest rate of income tax. How you get it depends on the type of scheme:</p>
'''+table(['Method','How relief is given','Typical schemes'],[['Relief at source','You pay from taxed pay; the provider claims 20% from HMRC (£80 becomes £100). Higher and additional-rate relief must be claimed.','Personal pensions, SIPPs, many workplace schemes'],['Net pay arrangement','Contribution taken before income tax, so full relief is automatic. Non-taxpayers get no relief.','Many occupational schemes'],['Salary sacrifice','You give up salary; employer pays it in. Saves income tax and National Insurance.','Workplace schemes that offer it']])+'''
<h3>Relief by tax band (England, Wales and Northern Ireland)</h3>
'''+table(['Income','Income tax rate','Relief added automatically (relief at source)','Extra you can claim','Cost of £100 in the pension'],[['£12,571 – £50,270','20%','£20','—','£80'],['£50,271 – £125,140','40%','£20','£20','£60'],['£100,000 – £125,140 (allowance taper zone)','effective 60%','£20','£20 + allowance won back','as low as £40'],['Over £125,140','45%','£20','£25','£55']])+'''
<p class="note">Bands are frozen until 2031 (Autumn Budget, 28 October 2026). Scottish taxpayers still get 20% added at source but claim extra at their Scottish rates; non-taxpayers still get the 20% on up to £3,600 gross a year.</p>
<h3>Worked examples (relief at source)</h3>
'''+table(['Income','You pay in','In the pension','Extra relief claimed','Real cost','Effective relief'],[['£40,000','£4,000','£5,000','£0','£4,000','20%'],['£60,000','£4,000','£5,000','£1,000','£3,000','40%'],['£60,000','£8,000','£10,000','£1,946','£6,054','39%'],['£110,000','£8,000','£10,000','£2,000 + £2,000 allowance','£4,000','60%'],['£150,000','£8,000','£10,000','£2,500','£5,500','45%']])+'''
<p class="note">At £60,000 with £10,000 gross, only £9,730 of the income is taxed at 40%, so the extra relief is 20% of £9,730. At £150,000 the personal allowance is already fully lost and is not restored by a £10,000 contribution.</p>
<h3>Limits to know</h3>
<ul><li><b>Annual allowance:</b> £60,000 gross a year across all your pensions, including employer contributions. Unused allowance from the previous three tax years can usually be carried forward.</li><li><b>Earnings cap on relief:</b> relief only on personal contributions up to 100% of your UK relevant earnings, or £3,600 gross if higher.</li><li><b>Tapered allowance:</b> reduces by £1 for every £2 of adjusted income above £260,000, to a minimum of £10,000 (applies only if threshold income is also over £200,000).</li><li><b>Money purchase annual allowance:</b> £10,000 once you have flexibly taken taxable income from a defined contribution pension.</li></ul>
<h3>Salary sacrifice change from April 2029</h3>
<p>The Autumn Budget 2025 announced that from <b>6 April 2029</b> National Insurance relief on salary-sacrificed pension contributions will be capped at <b>£2,000 a year</b> per employee; amounts above that will pay employee and employer NI like normal salary. Income tax relief is not affected.</p>
<h3>How to claim the extra relief</h3>
<ul><li>If you file Self Assessment, enter your gross personal pension contributions (net payment × 1.25) in the pensions section.</li><li>If you don't, contact HMRC with your contribution details; they will usually change your tax code or send a repayment.</li><li>You can backdate claims for up to four previous tax years.</li></ul>
'''+faq_html(FAQ)+'''
<p class="note">Sources (checked 20 Nov 2026): HMRC Pensions Tax Manual and GOV.UK guidance on tax on your private pension contributions (relief at source, £3,600 limit, £60,000 annual allowance, taper above £260,000 adjusted income, £10,000 MPAA); <a href="https://www.gov.uk/government/publications/changes-to-salary-sacrifice-for-pensions-from-april-2029" rel="nofollow">HM Treasury — Changes to salary sacrifice for pensions from April 2029</a> (£2,000 NI cap); <a href="https://www.which.co.uk/news/article/autumn-budget-2026-when-is-it-and-what-will-it-contain-aQqC47O24jnl" rel="nofollow">Autumn Budget 28 October 2026 summary</a> (income tax thresholds frozen to 2031). England, Wales and NI rates for 2026/27. Not financial advice.</p>'''
print(build('/uk/pension-tax-relief-calculator.html','Pension Tax Relief Calculator UK 2026/27 – 20%, 40%, 45% & the 60% Trap',
 'See what a pension contribution really costs after tax relief: 20% added at source, extra 20%/25% for higher and additional-rate taxpayers, the 60% band between £100,000 and £125,140, and 2026/27 limits.',art,FAQ,form=form,calc=calc))
